CREATE OR REPLACE FUNCTION public.account_deletion_requests_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.user_id is distinct from old.user_id or new.requested_at is distinct from old.requested_at then
    raise exception 'account_deletion_requests: user_id and requested_at are immutable';
  end if;
  new.updated_at := now();
  if new.status = 'completed' then new.completed_at := coalesce(old.completed_at, now()); else new.completed_at := null; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.assessment_drafts_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' then
    new.created_at := now();
  elsif old.expires_at <= now() then
    new.created_at := now();
  else
    new.created_at := old.created_at;
  end if;
  new.expires_at := least(now() + interval '48 hours', new.created_at + interval '7 days');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_athletes_coach_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Only direct API writes are checked. current_setting('role') is the PostgREST role and stays the same inside
  -- SECURITY DEFINER functions (same test the coaches service policy uses). service_role, migrations and the FK's
  -- ON DELETE SET NULL pass.
  if coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.coach_id is not distinct from old.coach_id then
    return new;
  end if;
  if new.coach_id is null then
    return new;  -- unlink / Disconnect always allowed
  end if;
  if current_setting('romrx.coach_connect', true) = new.coach_id::text then
    return new;  -- set by connect_coach_by_email in this transaction
  end if;
  -- SECURITY DEFINER so this lookup can see coaches/users (athletes cannot read other users' rows under RLS).
  if not exists (
    select 1
    from public.coaches c
    join public.users u on u.id = c.user_id
    where c.id = new.coach_id
      and u.portal_role = 'coach'
      and c.user_id is distinct from auth.uid()
  ) then
    raise exception 'athletes: coach_id must be an existing coach'
      using errcode = '42501', hint = 'Connect a coach with connect_coach_by_email.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_coaches_self_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Only direct API writes are checked (same test as guard_athletes_coach_id). service_role, migrations and the invite flow pass.
  IF coalesce(current_setting('role', true), 'none') NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'coaches: a coach row can only be your own' USING errcode = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'coaches: user_id cannot change' USING errcode = '42501';
  END IF;
  -- portal_role and school_id on users are protected columns (service role / admin only), so these two checks cannot be self-set.
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = NEW.user_id AND u.portal_role = 'coach'
                 AND NEW.school_id IS NOT DISTINCT FROM u.school_id) THEN
    RAISE EXCEPTION 'coaches: coach role and school are assigned by ROMRx, not self-set' USING errcode = '42501',
      HINT = 'Ask support to enable the coach account.';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.notif_opt_in_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      new.retest_opt_in_at := null; new.protocol_opt_in_at := null; new.digest_opt_in_at := null;
    else
      new.retest_opt_in_at := old.retest_opt_in_at; new.protocol_opt_in_at := old.protocol_opt_in_at; new.digest_opt_in_at := old.digest_opt_in_at;
    end if;
  end if;
  if new.retest_reminders   is not true then new.retest_opt_in_at   := null; end if;
  if new.email_reminders    is not true then new.protocol_opt_in_at := null; end if;
  if new.weekly_digest      is not true then new.digest_opt_in_at   := null; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.reject_under_18_age_bucket()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.age_bucket = any (array['13-17'])
     and (tg_op = 'INSERT' or new.age_bucket is distinct from old.age_bucket) then
    raise exception 'ROMRx is for adults 18 and older (age_bucket %)', new.age_bucket
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.romood_enforce_daily_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  day_start timestamptz;
  n integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('romood_daily_cap:' || new.user_id::text, 0));
  -- Ignore any created_at the client sends (backdated or future). The row is stamped with server time,
  -- so the day count below, the cap, and the email window cannot be skipped by faking a time.
  new.created_at := now();
  day_start := (date_trunc('day', now() at time zone 'America/New_York')) at time zone 'America/New_York';
  select count(*) into n
    from public.mood_entries
   where user_id = new.user_id
     and created_at >= day_start
     and created_at < day_start + interval '1 day';
  if n >= 4 then
    raise exception using errcode = 'RM429', message = 'romood_daily_cap',
      detail = 'Mood check-ins are limited to 4 per day (America/New_York).';
  end if;
  return new;
end;
$function$

