CREATE OR REPLACE FUNCTION public.sync_user_sports()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.platforms IS DISTINCT FROM OLD.platforms AND NEW.sports_enabled IS NOT DISTINCT FROM OLD.sports_enabled THEN
    NEW.sports_enabled := NEW.platforms;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.sports_enabled IS DISTINCT FROM OLD.sports_enabled AND NEW.platforms IS NOT DISTINCT FROM OLD.platforms THEN
    NEW.platforms := NEW.sports_enabled;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.platforms IS NOT NULL AND cardinality(NEW.platforms) > 0 AND NEW.sports_enabled IS NULL THEN
      NEW.sports_enabled := NEW.platforms;
    ELSIF NEW.sports_enabled IS NOT NULL AND cardinality(NEW.sports_enabled) > 0 AND (NEW.platforms IS NULL OR cardinality(NEW.platforms) = 0) THEN
      NEW.platforms := NEW.sports_enabled;
    END IF;
  END IF;
  IF NEW.sports_enabled IS NOT NULL AND cardinality(NEW.sports_enabled) > 0
     AND NOT (NEW.active_sport = ANY (NEW.sports_enabled)) AND NEW.active_sport <> 'general' THEN
    NEW.active_sport := NEW.sports_enabled[1];
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_assessments_compute_tiers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_secret text; v_headers jsonb;
begin
  select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds where ds.name = 'cron_webhook_secret';
  v_headers := jsonb_build_object('Content-Type','application/json');
  if v_secret is not null then v_headers := v_headers || jsonb_build_object('x-cron-secret', v_secret); end if;
  perform net.http_post(
    url := 'https://cqzvqzwwevnflinxgnpp.supabase.co/functions/v1/compute-tiers',
    body := jsonb_build_object('type','INSERT','table',tg_table_name,'schema',tg_table_schema,'record',to_jsonb(new),'old_record',null),
    headers := v_headers,
    timeout_milliseconds := 5000);
  return new;
exception when others then
  raise warning 'compute-tiers trigger call failed: %', sqlerrm;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.tg_pe_ai_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sport text;
begin
  if new.role = 'user' then
    select sport into v_sport from public.ai_conversations where id = new.conversation_id;
    perform public.log_product_event(new.user_id, 'rombot_message_sent',
      jsonb_build_object('conversation_id', new.conversation_id, 'chars', length(coalesce(new.content, ''))), v_sport);
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tg_pe_assessment_inserted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_measured int; v_prior int;
begin
  select count(*) into v_measured from jsonb_each_text(to_jsonb(new)) e
   where e.value is not null and (e.key like 'hip_%' or e.key like 'shoulder_%' or e.key like 'ankle_%' or e.key like 'cervical_%' or e.key like 'lumbar_%' or e.key like 'thoracic_%' or e.key like 'balance_%');
  select count(*) into v_prior from public.assessments a where a.user_id = new.user_id and a.id <> new.id;
  perform public.log_product_event(new.user_id, 'assessment_submitted',
    jsonb_build_object('assessment_id', new.id, 'measured_fields', v_measured, 'is_reassessment', v_prior > 0, 'prior_count', v_prior),
    new.sport);
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tg_pe_user_base_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.base_status is distinct from old.base_status then
    perform public.log_product_event(new.id, 'base_status_changed',
      jsonb_build_object('from', old.base_status, 'to', new.base_status, 'base_expiry', new.base_expiry), new.active_sport);
    if new.base_status = 'active' then
      perform public.log_product_event(new.id, 'base_activated', jsonb_build_object('base_expiry', new.base_expiry), new.active_sport);
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tg_webhook_feedback_to_notion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_secret text;
begin
  select ds.decrypted_secret into v_secret
  from vault.decrypted_secrets ds
  where ds.name = 'feedback_to_notion_webhook_secret';
  if v_secret is null then
    raise warning 'tg_webhook_feedback_to_notion: vault secret missing; webhook skipped for %', new.id;
    return new;
  end if;
  perform net.http_post(
    url := 'https://cqzvqzwwevnflinxgnpp.supabase.co/functions/v1/feedback-to-notion',
    body := jsonb_build_object(
      'type', 'INSERT', 'schema', tg_table_schema, 'table', tg_table_name,
      'record', to_jsonb(new), 'old_record', null),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-webhook-secret', v_secret),
    timeout_milliseconds := 5000
  );
  return new;
exception when others then
  raise warning 'tg_webhook_feedback_to_notion failed (insert not blocked): %', sqlerrm;
  return new;
end;
$function$

